"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[7361],{45104:e=>{e.exports=JSON.parse('{"tag":{"label":"Connector","permalink":"/datagol-knowlegde-base-v1/docs/tags/connector","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":18,"items":[{"id":"Lakehouse/Data sources/About Data sources","title":"About Data sources","description":"From the Data Source section you can connect to a wide range of data platforms. This module supports integration with popular services such as MySQL, MS SQL Server, DB2, and Postgres databases through a user-friendly authentication and authorization workflow.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/About Data sources"},{"id":"Lakehouse/Pipelines/About pipelines","title":"About pipelines","description":"Data pipeline is a structured workflow that facilitates the movement and transformation of data from various data sources into your central warehouse and also in another data source. A pipeline can be compared to a conveyor belt that picks up data, performs specific actions on it, and then deposits it in its designated location.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Pipelines/about-pipelines"},{"id":"Lakehouse/Orchestrations/Adding members to an orchestration","title":"Adding members to an orchestration","description":"You can add users to an orchestration. If they do not already have access to associated pipelines, they can be granted permissions. Only Lakehouse members can be added, and they will receive creator permissions by default.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/adding-members-to-orchestration"},{"id":"Lakehouse/Data sources/Connecting Data sources","title":"Connecting Data sources","description":"Only an Account admin or Lakehouse admin can add data sources.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/adding-data-sources"},{"id":"Lakehouse/Orchestrations/Creating orchestrations","title":"Creating orchestrations","description":"Orchestration in DataGOL allows you to define and manage the execution order of multiple pipelines. This is crucial when you have dependencies between pipelines, where one pipeline needs to complete successfully before another can begin. Without orchestration, scheduling pipelines to run independently might lead to failures or unexpected results if a dependent pipeline runs before its required data is ready.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/creating-orchestration"},{"id":"Lakehouse/Orchestrations/Deleting an orchestration","title":"Deleting an orchestration","description":"To delete an orchestration, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/deleting-an-orchestration"},{"id":"Lakehouse/Data sources/Designating a partition column","title":"Designating a partition column","description":"To designate a partition column, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/designating-a-partition-column"},{"id":"Lakehouse/Orchestrations/Editing an orchestration","title":"Editing an orchestration","description":"To edit an orchestration, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/editing-an-orchestration"},{"id":"Lakehouse/Data sources/Generating column metadata catalog with AI","title":"Generating column metadata catalog with AI","description":"To generate the column metadata catalog using AI, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/generating-column-metadata-catalog-with-ai"},{"id":"Lakehouse/Jobs","title":"Jobs","description":"Navigate to Jobs: Under the Lakehouse section, go to Jobs.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/jobs"},{"id":"Lakehouse/Data sources/Managing Data sources","title":"Managing Data sources","description":"-   Data sources can be sorted by creation date, displaying either the latest or oldest entries.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/managing-data-sources"},{"id":"Lakehouse/Orchestrations/Managing orchestrations","title":"Managing orchestrations","description":"You can manage and monitor the orchestrations from the Orchestrations page. The main Orchestration page display a list of all created orchestrations.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/managing-orchestration"},{"id":"Lakehouse/Orchestrations/Running an orchestration","title":"Running an orchestration","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Orchestration. The list of created orchestrations is displayed.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/running-an-orchestration"},{"id":"Lakehouse/Schema change detection","title":"Schema change detection","description":"DataGOL\'s Schema Change Detection feature monitors the source tables involved in your pipelines for any modifications to their structure (e.g., new columns, deleted columns, data type changes). This helps you stay informed about potential impacts on your data pipelines and warehouse. When a schema change is detected, it is recorded, indicating the table, the modified columns, and the nature of the change (e.g., data type, size).","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/schema-change-detection"},{"id":"Lakehouse/Orchestrations/Updating the orchestration settings","title":"Updating the orchestration settings","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Orchestration.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/updating-the-orchestration-settings"},{"id":"Lakehouse/Orchestrations/Viewing pipeline details of an orchestration","title":"Viewing pipeline details of an orchestration","description":"From the Pipelines tab of an orchestration, you can view the specifics of each pipeline within an orchestration. Click a pipeline link to access its comprehensive details, including its data source and destination. Furthermore, you can find information about the pipeline\'s creator and its designated stage order. For granular insights, the status and job stage details are readily available. To explore the data lineage, scroll right and click the more options icon.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/viewing-pipeline-details-of-an-orchestration"},{"id":"Lakehouse/Orchestrations/Viewing the orchestration graph","title":"Viewing the orchestration graph","description":"The Graphs tab within an orchestration provides a clear visual representation of the pipeline\'s execution order, illustrating the sequence of stages. To view the orchestration graph do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/viewing-the-orchestration-graph"},{"id":"Lakehouse/Orchestrations/Viewing the orchestration run details","title":"Viewing the orchestration run details","description":"The Runs tab provides a comprehensive view of each orchestration execution. Here, you can readily see details such as the run\'s name, the user who initiated it, the start and end times, the total duration, and the current status (e.g., completed, failed). To investigate data lineage, click the more options icon. Additionally, clicking the View Snapshot link offers a detailed, point-in-time overview of that specific run.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/viewing-the-orchestration-run-details"}],"unlisted":false}}')}}]);